const itens = $('Escolher transportadoras').all().map(i => i.json);
const d = itens[0];
const cfg = $('Configuração').first().json;
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = ($input.first() && $input.first().json && $input.first().json.output) || {};
const intro = typeof out.introducao === 'string' ? out.introducao.trim() : '';
const fecho = typeof out.fecho === 'string' ? out.fecho.trim() : '';
const limpo = (t, max) => t.length > 0 && t.length <= max && !/https?:|www[.]|[<>€$]|EUR|USD/i.test(t);
const llmOk = limpo(intro, 700) && intro.includes(d.codigo) && limpo(fecho, 400);
const introFinal = llmOk ? intro : 'Exmos. Senhores, solicitamos uma cotação de frete para o pedido com a referência ' + d.codigo + ', cujos dados constam da tabela abaixo.';
const fechoFinal = llmOk ? fecho : 'Agradecemos a vossa resposta com a cotação e as respetivas condições.';
const linha = (k, v) => '<tr><td style="padding:4px 16px 4px 0"><b>' + k + '</b></td><td>' + esc(v) + '</td></tr>';
const redirecionado = !!cfg.destinatario_teste;
const nomes = itens.map(t => t.transportadora_nome).join(', ');
const emails = itens.map(t => t.transportadora_email).join(', ');
const destinatarioTo = redirecionado ? cfg.destinatario_teste : cfg.destinatario_principal;
const destinatariosBcc = redirecionado ? '' : emails;
const assunto = (redirecionado ? '[TESTE] ' : '') + '[' + d.codigo + '] Pedido de cotação de frete - ' + d.produto + ' - destino ' + d.destino_pais;
const corpo = (redirecionado ? '<p><i>Email de teste. Destinatários reais (em BCC): ' + esc(nomes) + '.</i></p>' : '')
  + '<p>' + esc(introFinal) + '</p>'
  + '<table>' + linha('Referência', d.codigo) + linha('Produto', d.produto) + linha('Densidade', d.densidade) + linha('Granulometria', d.granulometria)
  + linha('Quantidade', d.quantidade + ' ' + d.unidade) + linha('Embalagem', d.embalagem) + linha('Incoterm', d.incoterm) + linha('País de destino', d.destino_pais) + '</table>'
  + '<p><b>Pedimos que a resposta inclua:</b></p><ul><li>preço total do frete (indicar a moeda)</li><li>modo de transporte e prazo de trânsito em dias</li><li>validade da cotação</li><li>condições e eventuais custos adicionais (inland, taxas portuárias, outros)</li></ul>'
  + '<p><b>Importante:</b> mantenha a referência ' + esc(d.codigo) + ' no assunto da resposta.</p>'
  + '<p>' + esc(fechoFinal) + '</p><p>Cumprimentos,<br>Equipa comercial (mensagem enviada pelo sistema de propostas)</p>';
return itens.map(t => ({ json: Object.assign({}, t, { assunto: assunto, corpo_html: corpo, destinatario_to: destinatarioTo, destinatarios_bcc: destinatariosBcc, redirecionado_teste: redirecionado, gerado_por: llmOk ? 'llm' : 'modelo_fixo', modelo: cfg.modelo, total_transportadoras: itens.length, nomes_transportadoras: nomes }) }));

const p = $('Ler proposta').first().json;
const cfg = $('Configuração').first().json;
const MAX_TENTATIVAS = 5;
const todas = $('Ler transportadoras ativas').all().map(i => i.json).filter(t => t && t.id);
const pedidos = $('Ler pedidos já feitos').all().map(i => i.json).filter(r => r && r.transportadora_id);
// 'falhou' não conta como contactada: pode ser repetida até MAX_TENTATIVAS
const feitasIds = pedidos.filter(r => r.estado !== 'falhou').map(r => r.transportadora_id);
const falhadas = pedidos.filter(r => r.estado === 'falhou');
const anteriores = falhadas.reduce((m, r) => Math.max(m, Number(r.tentativas) || 1), 0);
const max = Number(cfg.maximo_transportadoras) || 5;
const doPais = todas.filter(t => Array.isArray(t.rotas) && t.rotas.includes(p.destino_pais));
if (doPais.length === 0) throw new Error('Não há transportadoras ativas para o destino ' + p.destino_pais + ' (proposta ' + p.codigo + '): nada foi enviado. Acrescente transportadoras ou rotas.');
const jaContactadas = doPais.filter(t => feitasIds.includes(t.id)).length;
const candidatas = doPais.filter(t => !feitasIds.includes(t.id)).sort((a, b) => a.nome.localeCompare(b.nome));
const vagas = max - jaContactadas;
if (candidatas.length === 0 || vagas <= 0) throw new Error('Todas as transportadoras já foram contactadas para a proposta ' + p.codigo);
if (anteriores >= MAX_TENTATIVAS) throw new Error('Proposta ' + p.codigo + ': o envio do pedido de cotação falhou ' + anteriores + ' vezes (máximo ' + MAX_TENTATIVAS + ') e NÃO foi tentado de novo. Verifique a ligação ao Outlook e envie o pedido manualmente.');
return [{ json: {
  codigo: p.codigo, produto: p.produto, quantidade: p.quantidade, unidade: p.unidade, incoterm: p.incoterm, destino_pais: p.destino_pais,
  alvo: Math.min(vagas, candidatas.length), vagas: vagas, ja_contactadas: jaContactadas, tentativa: anteriores + 1,
  candidatas: candidatas.map(t => ({ id: t.id, nome: t.nome, modos: t.modos || [], paises_servidos: t.rotas }))
} }];

